"""Write the Terraform outputs into the config files that ingestion and dbt read.

Usage: terraform output -json | python3 render_outputs.py <project_dir>
"""

import json
import sys
from pathlib import Path

GENERATED_HEADER = (
    "# Generated by scripts/save_outputs.sh; edit the .example template instead.\n"
)


def fill_template(template_path, values):
    """Return the template with each __PLACEHOLDER__ replaced by its value."""
    text = template_path.read_text(encoding="utf-8")
    for placeholder, value in values.items():
        # json.dumps wraps the value in quotes, which is also valid YAML.
        text = text.replace(placeholder, json.dumps(value))
    return GENERATED_HEADER + text.rstrip() + "\n"


def main():
    project_dir = Path(sys.argv[1]).resolve()
    outputs = json.load(sys.stdin)

    project_id = outputs["gcp_project_id"]["value"]
    raw_dataset_id = outputs["gcp_bigquery_raw_ingest_id"]["value"]
    transform_dataset_id = outputs["gcp_bigquery_transform_id"]["value"]
    raw_table_id = outputs["gcp_bigquery_sales_raw_table_name"]["value"]
    raw_logs_table_id = outputs["gcp_bigquery_sales_raw_logs_table_name"]["value"]

    outputs_json = json.dumps(outputs, indent=2) + "\n"
    dbt_dir = project_dir / "dbt"

    # Build every file before writing any, so a failure leaves the old files in place.
    files = {
        project_dir / "ingestion/outputs.json": outputs_json,
        dbt_dir / "outputs.json": outputs_json,
        dbt_dir / "profiles.yml": fill_template(
            dbt_dir / "profiles.yml.example",
            {
                "__GCP_PROJECT_ID__": project_id,
                "__TRANSFORM_DATASET_ID__": transform_dataset_id,
            },
        ),
        dbt_dir / "models/sources.yml": fill_template(
            dbt_dir / "models/sources.yml.example",
            {
                "__GCP_PROJECT_ID__": project_id,
                "__RAW_DATASET_ID__": raw_dataset_id,
                "__RAW_TABLE_ID__": raw_table_id,
                "__RAW_LOGS_TABLE_ID__": raw_logs_table_id,
            },
        ),
    }

    for path, text in files.items():
        path.write_text(text, encoding="utf-8")
        print(f"Saved {path}")


if __name__ == "__main__":
    main()
